@pytest.mark.parametrize('orientation', ['vertical', 'horizontal'])
@pytest.mark.parametrize('converter', ['auto', 'concise'])
@pytest.mark.parametrize('scalar_baseline', [False, True])
def test_bar_datetime_baseline(orientation, converter, scalar_baseline):
    start = np.array(['2012-01-01', '2012-02-01', '2012-01-15'],
                     dtype='datetime64[h]')
    stop = np.array(['2012-02-07T12', '2012-02-13T06', '2012-02-12T18'],
                    dtype='datetime64[h]')
    if scalar_baseline:
        start = start[0]
    with mpl.rc_context({'date.converter': converter}):
        fig, ax = plt.subplots()
        if orientation == 'vertical':
            bars = ax.bar([0, 1, 3], height=stop - start, bottom=start)
            axis = ax.yaxis
            origins = [bar.get_y() for bar in bars]
            lengths = [bar.get_height() for bar in bars]
        else:
            bars = ax.barh([0, 1, 3], width=stop - start, left=start)
            axis = ax.xaxis
            origins = [bar.get_x() for bar in bars]
            lengths = [bar.get_width() for bar in bars]
        assert isinstance(axis.get_major_locator(), mdates.AutoDateLocator)
        formatter = (mdates.AutoDateFormatter if converter == 'auto'
                     else mdates.ConciseDateFormatter)
        assert isinstance(axis.get_major_formatter(), formatter)
        assert_allclose(origins, mdates.date2num(start))
        assert_allclose(lengths, mdates.date2num(stop) - mdates.date2num(start))
        fig.canvas.draw()


